/* Military veterans — medal shown next to their names everywhere */
const VETERANS = new Set([
  "moses thurston",
  "phillip nuffer",
  "phillip george nuffer",
  "phil nuffer",
  "stuart nuffer",
  "stuart lee nuffer",
  "shawn nuffer",
  "shawn thomas nuffer",
  "seth anderson",
  "seth douglass anderson",
  "jessica anderson",
  "jessica nuffer",
  "jessica anne nuffer",
]);

function isVeteran(name) {
  if (!name) return false;
  return VETERANS.has(name.toLowerCase().trim());
}

function MedalName({ name, style }) {
  const vet = isVeteran(name);
  return (
    <span style={style}>
      {name}
      {vet && (
        <span
          title="Veteran"
          style={{ marginLeft:"0.3em", fontSize:"0.9em", display:"inline-block", verticalAlign:"middle" }}
        >
          🎖️
        </span>
      )}
    </span>
  );
}

